// sec-researcher trigger 1/3: ONE Flux notification-controller event (Provider type generic, POSTed by the
// `n8n-agents` Provider in clusters/pi-k3s/flux-notifications/n8n-agents.yaml) → the trigger record for
// `Trigger`. Returns NO items (the execution ends quietly) unless it is an info event that names a commit sha
// and comes from one of the two shapes below. Nothing from the payload except the validated 40-hex sha is used.
//
// - GitRepository (what the Alert sends now): source-controller's `NewArtifact` event, emitted once per new
//   artifact ("stored artifact for commit '…'"), metadata.revision = "main@sha1:<sha>" — the artifact the agent's
//   checkout downloads exists at that moment.
// - Kustomization (the old Alert, still accepted): one `ReconciliationSucceeded` per Kustomization per reconcile,
//   same metadata.revision shape.
// `Claim` keeps exactly one run per sha (key sec-researcher:flux-rev:<sha>, held for a year) whichever shape (and
// however many copies) arrive — the dedupe is the defence in depth, not the only filter.
const item = $input.first().json || {};
const p = (item.body && typeof item.body === 'object') ? item.body : item;   // webhook item, or a bare payload in tests
const obj = v => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const GROUP = { GitRepository: 'source.toolkit.fluxcd.io', Kustomization: 'kustomize.toolkit.fluxcd.io' };

if (p.severity !== 'info') return [];
const kind = obj(p.involvedObject).kind;
if (!Object.prototype.hasOwnProperty.call(GROUP, kind)) return [];
const meta = obj(p.metadata);
// notification-controller trims the involved object's group prefix from metadata keys; accept both forms.
const raw = String(meta.revision || meta[`${GROUP[kind]}/revision`] || '');
const m = raw.match(/(?:^|[@:])([0-9a-f]{40})$/);
if (!m) return [];
const revision = m[1];

return [{ json: {
  trigger: 'flux',
  revision,
  dedupe_key: `sec-researcher:flux-rev:${revision}`,
  subject: revision,
  cooldown_hours: 24 * 365,
} }];

// sec-researcher trigger 2/3: the ONE named weekly sweep (design §10: the only scheduled poll). One run per ISO
// week: Claim holds sec-researcher:sweep:<YYYY-Www> for 6 days, so a re-fired schedule (n8n restart, a
// manual "execute") in the same week does nothing.
const now = new Date();
// ISO week of `now` (UTC): Thursday of this week decides the year.
const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const dow = d.getUTCDay() || 7;
d.setUTCDate(d.getUTCDate() + 4 - dow);
const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
const isoWeek = `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;

return [{ json: {
  trigger: 'sweep',
  week: isoWeek,
  dedupe_key: `sec-researcher:sweep:${isoWeek}`,
  subject: `sweep:${isoWeek}`,
  cooldown_hours: 24 * 6,
} }];

// sec-researcher trigger 3/3: Matt's form (LAN only, https://n8n.lab.mtgibbs.dev/form/agent-sec-run). The text is
// DATA: it only ever lands in event.data.ask (a JSON POST body). Each submission is its own run (fresh key).
const MAX_ASK = 4000;
let f = {};
try { f = $('Sec Form').first().json || {}; } catch (e) { f = $input.first().json || {}; }
const ask = String(f['What should it focus on? (optional)'] || f.ask || '').trim().slice(0, MAX_ASK);

const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let t = Date.now(), time = '';
for (let i = 0; i < 10; i++) { time = B32[t % 32] + time; t = Math.floor(t / 32); }
let rand = '';
for (let i = 0; i < 16; i++) rand += B32[Math.floor(Math.random() * 32)];
const key = time + rand;

return [{ json: {
  trigger: 'manual',
  ask: ask || 'General access-control review of clusters/pi-k3s/. Start with what faces the outside.',
  dedupe_key: `sec-researcher:manual:${key}`,
  subject: 'manual',
  cooldown_hours: 1,
} }];

// The one merge point of the three sec-researcher triggers (Flux Revision / Sweep Input / Form Input). Later
// nodes read $('Trigger'). It re-checks the record's shape, so nothing downstream (Claim's SQL parameter, the
// GitHub compare URL, the event) ever sees a value that did not come from one of the three input nodes.
const t = $input.first().json || {};
const KEY = /^sec-researcher:(flux-rev:[0-9a-f]{40}|sweep:\d{4}-W\d{2}|manual:[0-9A-Z]{26})$/;
if (!['flux', 'sweep', 'manual'].includes(t.trigger)) throw new Error('unknown trigger');
if (!KEY.test(String(t.dedupe_key || ''))) throw new Error('malformed dedupe_key');
if (t.trigger === 'flux' && !/^[0-9a-f]{40}$/.test(String(t.revision || ''))) throw new Error('flux trigger without a revision');
const hours = Number(t.cooldown_hours);
return [{ json: {
  trigger: t.trigger,
  dedupe_key: t.dedupe_key,
  subject: String(t.subject || '').slice(0, 64),
  cooldown_hours: Number.isInteger(hours) && hours >= 1 ? hours : 1,
  revision: t.trigger === 'flux' ? t.revision : null,
  week: t.trigger === 'sweep' ? String(t.week || '').slice(0, 8) : null,
  ask: t.trigger === 'manual' ? String(t.ask || '').slice(0, 4000) : null,
} }];

// Which files did this revision change? Ask GitHub's PUBLIC API for the public pi-cluster repo (no token):
// compare <previous revision seen>...<this revision>, or, for the first revision ever seen, the commit itself
// (its diff against its first parent). The previous revision comes from Claim (the newest earlier
// sec-researcher:flux-rev row). Only validated 40-hex shas are put in the URL.
const REPO = 'mtgibbs/pi-cluster';
const SHA = /^[0-9a-f]{40}$/;
const t = $('Trigger').first().json;
const claim = $input.first().json || {};
const revision = String(t.revision || '');
if (!SHA.test(revision)) throw new Error('no revision to compare');
const base = SHA.test(String(claim.base || '')) && claim.base !== revision ? claim.base : null;
return [{ json: {
  revision,
  base,
  url: base
    ? `https://api.github.com/repos/${REPO}/compare/${base}...${revision}`
    : `https://api.github.com/repos/${REPO}/commits/${revision}`,
} }];

// Deterministic gate: did this revision touch access control? Input = the GitHub compare/commit response
// (HTTP node, full response, never error). Two tests, either is enough:
//   1. the PATH looks access-control-shaped (RBAC, ServiceAccounts, NetworkPolicies, ExternalSecrets,
//      ingress, namespaces, the agent sandbox, Flux itself, the secrets overlay);
//   2. a YAML file under clusters/ ADDED OR REMOVED a line with an access-control keyword (only +/- lines of
//      the patch — context lines and image-tag bumps do not count).
// Fails toward reviewing: a failed/odd API answer, a truncated file list (GitHub caps at 300) or a YAML
// patch GitHub omitted (too large) all count as relevant. The daily cap and per-revision dedupe bound that.
const PATHS = [
  /(^|\/)[^/]*(rbac|role|rolebinding|clusterrole|serviceaccount|networkpolic|external-secret|secretstore|secret-store|ingress|namespace|pod-security|psa)[^/]*\.ya?ml$/i,
  /^clusters\/pi-k3s\/(agents|harness-fleet|flux-system|flux-notifications|external-secrets|external-secrets-config|cloudflare-tunnel|tailscale|tailscale-config|ingress|cert-manager-config)\//,
  /^docs\/secrets-overlay\.yaml$/,
];
const KEYWORD = new RegExp([
  'kind:\\s*(Role|ClusterRole|RoleBinding|ClusterRoleBinding|ServiceAccount|NetworkPolicy|Ingress|IngressRoute|ExternalSecret|SecretStore|ClusterSecretStore|Namespace)\\b',
  'securityContext', 'privileged', 'allowPrivilegeEscalation', 'runAs(NonRoot|User|Group)', 'readOnlyRootFilesystem',
  'host(Network|PID|IPC|Path|Port)', 'capabilities', 'seccompProfile', 'automountServiceAccountToken',
  'serviceAccountName', 'secretKeyRef', 'secretRef', 'envFrom', 'remoteRef', 'pod-security\\.kubernetes\\.io',
  'ipBlock', 'namespaceSelector', 'podSelector', 'policyTypes', '\\bverbs:', '\\bapiGroups:', 'subjects:', 'roleRef:',
  'ingressClassName', 'tls:', 'nginx\\.ingress\\.kubernetes\\.io/(auth|whitelist|allowlist)',
].join('|'));
const MAX_PATHS = 50;

const r = $input.first().json || {};
let cmp = {};
try { cmp = $('Compare URL').first().json || {}; } catch (e) {}
const out = (relevant, why, changed, files_total) => [{ json: {
  relevant, why, revision: cmp.revision || null, base: cmp.base || null,
  changed_paths: changed.slice(0, MAX_PATHS).map(c => c.path),
  reasons: changed.slice(0, MAX_PATHS).map(c => `${c.path}: ${c.reason}`),
  files_total,
} }];

if (Number(r.statusCode) !== 200 || !r.body || typeof r.body !== 'object' || !Array.isArray(r.body.files)) {
  return out(true, `compare unavailable (HTTP ${r.statusCode || (r.error ? 'error' : '?')}); reviewing to be safe`, [], null);
}
const files = r.body.files.filter(f => f && typeof f.filename === 'string');
const changed = [];
for (const f of files) {
  const names = [f.filename, typeof f.previous_filename === 'string' ? f.previous_filename : null].filter(Boolean);
  const pathHit = names.find(n => PATHS.some(re => re.test(n)));
  if (pathHit) { changed.push({ path: f.filename, reason: 'path' }); continue; }
  const yaml = names.some(n => /^clusters\/.*\.ya?ml$/.test(n));
  if (!yaml) continue;
  if (typeof f.patch !== 'string') { changed.push({ path: f.filename, reason: 'diff too large to inspect' }); continue; }
  const hit = f.patch.split('\n').find(l => /^[+-]/.test(l) && !/^(\+\+\+|---)/.test(l) && KEYWORD.test(l));
  if (hit) changed.push({ path: f.filename, reason: `changed line matches "${(hit.match(KEYWORD) || [''])[0]}"` });
}
if (files.length >= 300) {
  return out(true, `${files.length} files changed (GitHub truncates the list at 300); reviewing to be safe`, changed, files.length);
}
return out(changed.length > 0, changed.length ? `${changed.length} access-control file(s) changed` : 'no access-control change', changed, files.length);

// Build the runner request {agent, event} for sec-researcher (CONTRACT §1) from `Trigger` (and, for a Flux
// revision, `Path Filter`). Event types pick the agent's behaviour AND its model (the manifest's
// model.by_event_type: security.sweep runs on Sonnet, the rest on Haiku):
//   security.flux_revision  data {revision, base, changed_paths, reasons, files_total}  source flux
//   security.sweep          data {scope, week}                                         source schedule
//   security.manual         data {ask}                                                 source matt
// event.data.revision (flux only, 40 hex) is the ONE event field the runner reads: it picks the Flux
// artifact the checkout fetches. trust is internal for all three (Flux events and the schedule are in-cluster;
// the form is LAN-only); the repo content the agent reads is still data, and its prompt says so.
const AGENT = 'sec-researcher';
const t = $('Trigger').first().json;
let pf = null;
try { pf = $('Path Filter').first().json; } catch (e) { pf = null; }

const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
let ms = Date.now(), time = '';
for (let i = 0; i < 10; i++) { time = B32[ms % 32] + time; ms = Math.floor(ms / 32); }
let rand = '';
for (let i = 0; i < 16; i++) rand += B32[Math.floor(Math.random() * 32)];
const id = time + rand;
const line = s => String(s || '').replace(/[\u0000-\u001f\u007f]+/g, ' ').trim();

let type, source, subject, data;
if (t.trigger === 'flux') {
  if (!pf || !pf.relevant) throw new Error('flux trigger reached Build Event without a relevant Path Filter result');
  type = 'security.flux_revision'; source = 'flux';
  subject = `rev:${t.revision.slice(0, 12)}`;
  data = {
    revision: t.revision,
    base: /^[0-9a-f]{40}$/.test(String(pf.base || '')) ? pf.base : null,
    changed_paths: (pf.changed_paths || []).slice(0, 50).map(p => line(p).slice(0, 300)),
    reasons: (pf.reasons || []).slice(0, 50).map(p => line(p).slice(0, 400)),
    files_total: Number.isInteger(pf.files_total) ? pf.files_total : null,
    why: line(pf.why).slice(0, 300),
  };
} else if (t.trigger === 'sweep') {
  type = 'security.sweep'; source = 'schedule';
  subject = `sweep:${t.week}`;
  data = { scope: 'clusters/pi-k3s/', week: t.week };
} else {
  type = 'security.manual'; source = 'matt';
  subject = 'manual';
  data = { ask: String(t.ask || '').slice(0, 4000) };
}

const label = t.trigger === 'flux' ? `Flux revision ${t.revision.slice(0, 7)}` : t.trigger === 'sweep' ? `weekly sweep ${t.week}` : 'manual run';
return [{ json: {
  agent: AGENT,
  trigger: t.trigger,
  label,
  event: { id, type, source, subject, dedupe_key: t.dedupe_key, trust: 'internal', data },
} }];

// Derive an IN-CLUSTER resume URL for the "Wait for Result" node and attach it as `callback`.
//
// $execution.resumeUrl is "<WEBHOOK_URL>webhook-waiting/<executionId>?signature=<resumeToken>".
// WEBHOOK_URL is the PUBLIC tunnel host, which only passes ^/webhook/inbound-mail.* — so we
// keep n8n's path + query (the signature IS the per-execution auth; n8n 2.x rejects a resume
// without it: 401 {"error":"Invalid token"}) and swap the origin for the webhook tier's
// in-cluster Service. Both the main and the webhook process serve /webhook-waiting/*
// (N8N_DISABLE_PRODUCTION_MAIN_PROCESS is unset); waiting executions are looked up in
// Postgres by id, so no activation/registration is involved and no webhook-tier roll is needed.
const CALLBACK_ORIGIN = 'http://n8n-webhook.n8n.svc.cluster.local:5678';

const resumeUrl = String($execution.resumeUrl || '');
const m = resumeUrl.match(/^https?:\/\/[^/]+(\/.*)$/);
if (!m) throw new Error(`Unexpected $execution.resumeUrl shape: "${resumeUrl}"`);
const pathAndQuery = m[1];

// Fail now, not 30 minutes from now: the URL must be /webhook-waiting/<this execution>?…signature=…
const shape = pathAndQuery.match(/^\/webhook-waiting\/([^/?#]+)\?(?:[^#]*&)?signature=[^&#]+/);
if (!shape) {
  throw new Error('resumeUrl is not "/webhook-waiting/<id>?signature=<token>" at the root of WEBHOOK_URL — '
    + 'n8n changed its resume-URL shape or WEBHOOK_URL gained a path; see docs/agent-sandbox-n8n.md');
}
if (String(shape[1]) !== String($execution.id)) {
  throw new Error(`resumeUrl execution id ${shape[1]} != $execution.id ${$execution.id}`);
}

const item = $input.first().json;
return [{ json: { ...item, callback: CALLBACK_ORIGIN + pathAndQuery } }];

// sec-researcher's copy of agent-parse-result.js: the same ledger row, but `plan` outputs keep their STRUCTURE
// (severity, fingerprint, the seven sections) instead of being flattened to kind/title/body — n8n files issues
// from those fields. Everything is clipped and type-checked here; Plan Items re-validates before filing.
const OUTCOMES = ['done', 'nothing_to_do', 'needs_human', 'failed'];
const EXIT_REASONS = ['completed', 'deadline', 'job_failed', 'no_result', 'invalid_result', 'queue_expired'];
const SECTIONS = ['found', 'evidence', 'likely_cause', 'proposed_change', 'risk', 'verify', 'rollback'];

const body = ($input.first().json || {}).body;
if (!body || typeof body !== 'object') throw new Error('Callback has no JSON body');
const str = (v, n) => (typeof v === 'string' ? v : (v === undefined || v === null ? '' : String(v))).slice(0, n);
const ts = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const d = typeof v === 'number' ? new Date(v < 1e12 ? v * 1000 : v) : new Date(String(v));
  return isNaN(d.getTime()) ? null : d.toISOString();
};
const run_id = str(body.run_id, 128).trim();
if (!/^[A-Za-z0-9._:-]{1,128}$/.test(run_id)) throw new Error('Callback run_id missing or malformed');

const result = (body.result && typeof body.result === 'object') ? body.result : {};
const exit_reason = EXIT_REASONS.includes(body.exit_reason) ? body.exit_reason : str(body.exit_reason || 'unknown', 64);
const outcome = OUTCOMES.includes(result.outcome) ? result.outcome : 'failed';
const obj = v => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const outputs = (Array.isArray(result.outputs) ? result.outputs : [])
  .filter(o => o && typeof o === 'object')
  .slice(0, 20)
  .map(o => {
    if (o.kind !== 'plan') return { kind: str(o.kind, 64), title: str(o.title, 300), body: str(o.body, 32768) };
    const fp = obj(o.fingerprint), plan = obj(o.plan);
    const sections = {};
    for (const k of SECTIONS) sections[k] = str(plan[k], k === 'evidence' ? 8192 : 4096);
    return { kind: 'plan', title: str(o.title, 200), severity: str(o.severity, 16),
             fingerprint: { rule: str(fp.rule, 64), resource: str(fp.resource, 320) }, plan: sections };
  });

let ev = null;
try { ev = $('Build Event').first().json.event; } catch (e) { ev = null; }
return [{ json: {
  run_id,
  agent: str(body.agent, 64),
  event_id: str(body.event_id || (ev && ev.id), 128) || null,
  event_type: ev ? str(ev.type, 128) : null,
  subject: ev ? str(ev.subject, 200) : null,
  started: ts(body.started),
  finished: ts(body.finished),
  exit_reason,
  outcome,
  summary: str(result.summary, 2048),
  outputs,
} }];

// The Wait node resumed on its 80-minute limit, not on a callback. 80 = RUNNER_MAX_QUEUE_WAIT (45m) +
// sec-researcher's timeout (20m) + the runner's 5m deadline grace + ~10m for polling and callback retries.
// The Wait's output is its INPUT (the runner's 202), so run_id is known. A late callback can no longer resume
// this execution (409); the runner keeps its record at GET /runs/<run_id>. No plans are filed for it.
const r = $input.first().json || {};
const launched = (r.body && typeof r.body === 'object') ? r.body : {};
let ev = {}, agent = '';
try { const b = $('Build Event').first().json; ev = b.event || {}; agent = b.agent || ''; } catch (e) {}
const run_id = String(launched.run_id || '').slice(0, 128);
if (!run_id) throw new Error('Timed out, and the launch response had no run_id');
return [{ json: {
  run_id, agent, event_id: ev.id || null, event_type: ev.type || null, subject: ev.subject || null,
  started: null, finished: new Date().toISOString(), exit_reason: 'callback_timeout', outcome: 'failed',
  summary: 'No callback from agent-runner within 80 minutes. Check GET /runs/' + run_id
    + ' on the runner and the Job run-' + run_id + ' in namespace agents. No plans were filed.',
  outputs: [],
} }];

// The runner did not start the run (non-202, or unreachable via the HTTP node's error output): ONE agent_runs
// row so it is visible, then the normal tail (one push). No retry: sec-researcher runs are few, a Flux revision
// is claimed once, and the weekly sweep re-covers anything a refused run missed.
const r = $input.first().json || {};
let agent = '', ev = {};
try { const b = $('Build Event').first().json; agent = b.agent || ''; ev = b.event || {}; } catch (e) {}
const code = Number(r.statusCode || 0);
const body = (r.body && typeof r.body === 'object') ? r.body : {};
const detail = String(typeof r.body === 'string' ? r.body : (body.error || body.detail || body.message || '')).slice(0, 300);
const WHY = {
  200: 'this event id was already launched earlier (unexpected: event ids are fresh per launch)',
  401: 'runner rejected the bearer token (check the agent-runner credential)',
  404: 'runner does not know this agent (is the sec-researcher manifest deployed?)',
  422: 'runner rejected the manifest, event, or callback URL (a runner older than 0.3.0 rejects the checkout/by_event_type keys)',
  429: 'daily run cap or cluster quota reached',
  502: 'runner hit a Kubernetes error launching the Job',
  503: 'runner is paused (RUNNER_PAUSED=true)',
};
let exit_reason, summary;
if (r.error) {
  const e = typeof r.error === 'object' ? (r.error.message || JSON.stringify(r.error)) : String(r.error);
  exit_reason = 'runner_unreachable';
  summary = `Not started: could not reach agent-runner: ${String(e).slice(0, 300)}`;
} else if (code === 429 && body.error === 'queue_full') {
  exit_reason = 'refused_queue_full';
  summary = `Not started (HTTP 429): runner queue is full${body.detail ? ` - ${String(body.detail).slice(0, 300)}` : ''}`;
} else {
  exit_reason = `refused_${code || 'unknown'}`;
  summary = `Not started (HTTP ${code || '?'}): ${WHY[code] || 'unexpected runner response'}${detail ? ` - ${detail}` : ''}`;
}
return [{ json: {
  run_id: `nolaunch-${String(ev.id || Date.now())}`.slice(0, 128),
  agent, event_id: ev.id || null, event_type: ev.type || null, subject: ev.subject || null,
  started: null, finished: new Date().toISOString(), exit_reason, outcome: 'failed',
  summary: summary.slice(0, 2048), outputs: [],
} }];

// From the ledger row just written (Insert Ledger ... RETURNING; no row = duplicate callback = nothing runs):
// take the agent's `plan` outputs, re-validate them, and turn each into the exact issue it would become.
// Plain code, no model: the issue title/body are built from the structured fields only, and every piece of
// agent-written text is neutralised (no HTML, links, images, @-mentions, #-references, or a forged marker).
//
// THE PLANS REPO. The one place it is named; Issue Pages / Decide read it from this node's output.
const PLANS_REPO = 'mtgibbs/homelab-plans';
const AGENT = 'sec-researcher';
const SEVERITIES = ['critical', 'high', 'medium', 'low', 'info'];
const SECTIONS = [['found', 'What was found'], ['evidence', 'Evidence'], ['likely_cause', 'Likely cause'],
  ['proposed_change', 'Proposed change'], ['risk', 'Risk'], ['verify', 'How to verify'], ['rollback', 'How to roll back']];
const RULE = /^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$/;
const RESOURCE = /^[a-z0-9][a-z0-9.-]{0,62}\/[A-Z][A-Za-z0-9]{0,62}\/[A-Za-z0-9][A-Za-z0-9._:-]{0,252}$/;
const SECTION_CAP = 6000, EVIDENCE_CAP = 12000;   // escaped chars; keeps a body well under GitHub's 65536
if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(PLANS_REPO)) throw new Error('PLANS_REPO is not owner/repo');

function sha256hex(str) {
  const b = [];                                  // UTF-8 encode
  for (const ch of str) {
    let c = ch.codePointAt(0);
    if (c < 0x80) b.push(c);
    else if (c < 0x800) b.push(0xc0 | c >> 6, 0x80 | c & 63);
    else if (c < 0x10000) b.push(0xe0 | c >> 12, 0x80 | c >> 6 & 63, 0x80 | c & 63);
    else b.push(0xf0 | c >> 18, 0x80 | c >> 12 & 63, 0x80 | c >> 6 & 63, 0x80 | c & 63);
  }
  const K = [];
  for (let n = 2, found = 0; found < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (prime) { K.push((Math.pow(n, 1 / 3) % 1) * 4294967296 >>> 0); found++; }
  }
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bitLen = b.length * 8;
  b.push(0x80);
  while (b.length % 64 !== 56) b.push(0);
  for (let i = 7; i >= 0; i--) b.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let o = 0; o < b.length; o += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (b[o + 4 * i] << 24 | b[o + 4 * i + 1] << 16 | b[o + 4 * i + 2] << 8 | b[o + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, bb, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = bb; bb = a; a = (t1 + t2) >>> 0;
    }
    const v = [a, bb, c, d, e, f, g, h];
    for (let i = 0; i < 8; i++) H[i] = (H[i] + v[i]) >>> 0;
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

const ZW = '​';
// Prose: escape what GitHub would turn into markup that acts (HTML/comments, links, images, code spans,
// autolinks, mentions, issue references, headings). Formatting like * and _ is left alone: harmless.
const prose = (s, cap) => {
  let t = String(s || '').replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '');
  t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/([\\`\[\]])/g, '\\$1')
    .replace(/:\/\//g, ':' + ZW + '//').replace(/www\./gi, m => m.slice(0, 3) + ZW + '.')
    .replace(/@/g, '@' + ZW).replace(/#/g, '#' + ZW);
  return t.length > cap ? t.slice(0, cap) + '\n\n_[truncated by n8n]_' : t;
};
// Evidence: verbatim inside a fence longer than any backtick run in it (nothing in a fence renders), with
// HTML-comment openers broken so the raw body can never carry a second marker.
const fenced = (s, cap) => {
  let t = String(s || '').replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '').replace(/<!--/g, '<!' + ZW + '--');
  if (t.length > cap) t = t.slice(0, cap) + '\n[truncated by n8n]';
  const longest = Math.max(0, ...(t.match(/`+/g) || []).map(x => x.length));
  const fence = '`'.repeat(Math.max(3, longest + 1));
  return `${fence}text\n${t}\n${fence}`;
};
// Titles render as plain text on GitHub, but mentions/references still link: neutralise those, drop <>.
const oneLine = (s, n) => String(s || '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim()
  .replace(/@/g, '@' + ZW).replace(/#/g, '#' + ZW).slice(0, n);

const row = $input.first().json || {};
if (!row.run_id) return [];
let outputs = row.outputs;
if (typeof outputs === 'string') { try { outputs = JSON.parse(outputs); } catch (e) { outputs = []; } }
let ev = {}, label = '';
try { const b = $('Build Event').first().json; ev = b.event || {}; label = b.label || ''; } catch (e) {}
const revision = /^[0-9a-f]{40}$/.test(String((ev.data || {}).revision || '')) ? ev.data.revision : null;

const plans = [], seen = new Set();
let invalid = 0, duplicate = 0;
for (const o of Array.isArray(outputs) ? outputs : []) {
  if (!o || o.kind !== 'plan') continue;
  const fp = o.fingerprint || {}, p = o.plan || {};
  const ok = RULE.test(String(fp.rule || '')) && RESOURCE.test(String(fp.resource || '')) && SEVERITIES.includes(o.severity)
    && typeof o.title === 'string' && o.title.trim() && SECTIONS.every(([k]) => typeof p[k] === 'string' && p[k].trim());
  if (!ok) { invalid++; continue; }
  const fingerprint = sha256hex(`${AGENT}|${fp.rule}|${fp.resource}`);
  if (seen.has(fingerprint)) { duplicate++; continue; }
  seen.add(fingerprint);
  const content = [`**Severity:** ${o.severity} · **Rule:** \`${fp.rule}\` · **Resource:** \`${fp.resource}\``, '',
    '> Filed by n8n from a sec-researcher run. The text below was written by a model from untrusted inputs (the repo,',
    '> cluster state): treat it as a proposal and check the evidence. This issue IS the plan; nothing changes until it',
    '> is approved.', '',
    ...SECTIONS.flatMap(([k, h]) => [`### ${h}`, k === 'evidence' ? fenced(p[k], EVIDENCE_CAP) : prose(p[k], SECTION_CAP), ''])].join('\n');
  const content_hash = sha256hex(content);
  const body = [`<!-- sec-researcher-fingerprint: ${fingerprint} -->`, `<!-- sec-researcher-content: ${content_hash} -->`,
    content, '<!-- sec-researcher-footer -->', '---',
    `Last seen: run \`${String(row.run_id).replace(/[^A-Za-z0-9._:-]/g, '')}\` · ${revision ? `revision \`${revision.slice(0, 12)}\`` : 'revision n/a'} · ${new Date().toISOString().slice(0, 10)} · ${oneLine(label, 60) || 'n/a'}`,
    `Fingerprint: \`${AGENT} | ${fp.rule} | ${fp.resource}\` (sha256 \`${fingerprint.slice(0, 16)}…\`).`,
    'To accept the risk, close this issue as **not planned** (or add the `accepted-risk` label); later runs then leave it alone.',
    'Add notes as comments: a re-run that finds different details rewrites this body.'].join('\n');
  plans.push({ fingerprint, content_hash, rule: fp.rule, resource: fp.resource, severity: o.severity,
               title: `[sec][${o.severity}] ${oneLine(o.title, 200)}`.slice(0, 256), body,
               labels: ['sec-researcher', `severity:${o.severity}`] });
}
const rank = s => SEVERITIES.indexOf(s);
plans.sort((a, b) => rank(a.severity) - rank(b.severity));   // stable: most severe first, then agent order

return [{ json: {
  plans_repo: PLANS_REPO,
  run_id: row.run_id, agent: row.agent, outcome: row.outcome, exit_reason: row.exit_reason,
  summary: String(row.summary || '').slice(0, 2048),
  revision, plans, invalid, duplicate,
} }];

// One item per page of the plans repo's issues (all states, oldest first, 100 per page). `List Issues` fetches
// each with the github-plans credential; Decide reads every page and refuses to CREATE anything unless the
// listing is complete (a short page reached) and every page answered 200 — a partial view would mean
// duplicate issues. 5 pages = 500 issues; past that, Decide reports "lookup incomplete" and files nothing new.
const PAGES = 5;
const repo = $('Plan Items').first().json.plans_repo;
if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(String(repo))) throw new Error('bad plans repo');
return Array.from({ length: PAGES }, (_, i) => ({ json: {
  page: i + 1,
  url: `https://api.github.com/repos/${repo}/issues?state=all&per_page=100&sort=created&direction=asc&page=${i + 1}`,
} }));

// The exit point's decision, in plain code: for each plan (most severe first), find issues in the plans repo
// whose body STARTS with its fingerprint marker, then
//   - any match labelled `accepted-risk` (open or closed)   -> skip_accepted (do nothing)
//   - an open match                                         -> update its body if the content changed, else unchanged
//   - a match closed as "not planned"                       -> skip_accepted
//   - otherwise (none, or only closed-as-fixed = it came back) -> create, at most MAX_NEW per run;
//                                                             the rest are not_filed (reported in the push)
// If the issue listing failed, or was incomplete (5 full pages), nothing is created: a partial view would
// duplicate issues. Updates of issues that WERE seen still go ahead on an incomplete listing.
// Input: List Issues responses (one per page, full response, never error). Output: ONE item
// {actions: [create/update, with method/url/payload for Apply], decisions: [every plan's outcome]}.
const MAX_NEW = 5;
const pi = $('Plan Items').first().json;
const repo = pi.plans_repo;
if (!/^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/.test(String(repo))) throw new Error('bad plans repo');
const API = `https://api.github.com/repos/${repo}/issues`;
const FP = /^<!-- sec-researcher-fingerprint: ([0-9a-f]{64}) -->/;
const CONTENT = /^<!-- sec-researcher-content: ([0-9a-f]{64}) -->$/m;

const pages = $input.all().map(i => i.json || {});
let lookup = 'complete', issues = [];
if (!pages.length) lookup = 'failed';
for (const p of pages) {
  if (Number(p.statusCode) !== 200 || !Array.isArray(p.body)) { lookup = 'failed'; break; }
  issues = issues.concat(p.body);
}
if (lookup === 'complete' && !pages.some(p => p.body.length < 100)) lookup = 'incomplete';
if (lookup === 'failed') issues = [];
const lookupError = lookup === 'failed'
  ? `issue lookup failed (HTTP ${(pages.find(p => Number(p.statusCode) !== 200) || {}).statusCode || 'error'})` : null;

const byFp = new Map();
for (const i of issues) {
  if (!i || typeof i !== 'object' || i.pull_request || !Number.isInteger(i.number)) continue;
  const m = String(i.body || '').match(FP);
  if (!m) continue;
  const cm = String(i.body || '').match(CONTENT);
  const rec = { number: i.number, state: i.state, state_reason: i.state_reason || null,
                labels: (Array.isArray(i.labels) ? i.labels : []).map(l => (typeof l === 'string' ? l : (l && l.name) || '')),
                content: cm ? cm[1] : null };
  if (!byFp.has(m[1])) byFp.set(m[1], []);
  byFp.get(m[1]).push(rec);
}

const actions = [], decisions = [];
let created = 0;
for (const p of pi.plans || []) {
  const base = { fingerprint: p.fingerprint, rule: p.rule, resource: p.resource, severity: p.severity, title: p.title };
  if (lookup === 'failed') { decisions.push({ ...base, action: 'not_filed', reason: lookupError }); continue; }
  const matches = (byFp.get(p.fingerprint) || []).sort((a, b) => a.number - b.number);
  const labelled = matches.find(m => m.labels.includes('accepted-risk'));
  if (labelled) { decisions.push({ ...base, action: 'skip_accepted', issue_number: labelled.number }); continue; }
  const open = matches.find(m => m.state === 'open');
  if (open) {
    if (open.content === p.content_hash) { decisions.push({ ...base, action: 'unchanged', issue_number: open.number }); continue; }
    const d = { ...base, action: 'update', issue_number: open.number };
    decisions.push(d);
    actions.push({ ...d, method: 'PATCH', url: `${API}/${open.number}`, payload: { body: p.body } });
    continue;
  }
  const notPlanned = matches.find(m => m.state === 'closed' && m.state_reason === 'not_planned');
  if (notPlanned) { decisions.push({ ...base, action: 'skip_accepted', issue_number: notPlanned.number }); continue; }
  if (lookup === 'incomplete') {
    decisions.push({ ...base, action: 'not_filed', reason: 'issue lookup incomplete (over 500 issues); nothing new filed' });
    continue;
  }
  if (created >= MAX_NEW) { decisions.push({ ...base, action: 'not_filed', reason: `cap of ${MAX_NEW} new issues per run` }); continue; }
  created++;
  const fixed = matches.filter(m => m.state === 'closed').map(m => m.number);
  const body = fixed.length
    // The footer marker cannot occur in agent text (Plan Items escapes '<' in prose and breaks '<!--' in evidence).
    ? p.body.replace('\n<!-- sec-researcher-footer -->\n', `\n> Previously closed as fixed: ${fixed.map(n => `#${n}`).join(', ')}. It has come back.\n\n<!-- sec-researcher-footer -->\n`)
    : p.body;
  const d = { ...base, action: 'create', previously_fixed: fixed };
  decisions.push(d);
  actions.push({ ...d, method: 'POST', url: API, payload: { title: p.title, body, labels: p.labels } });
}
return [{ json: { lookup, lookup_error: lookupError, issues_seen: issues.length, actions, decisions } }];

// The end of every sec-researcher run that produced a ledger row: ONE ntfy push summarising it, and the
// filing rows for agent_plan_filings. Reached from three places (exactly one per execution):
//   Has Plans? false (no plans: a clean run, a failure, a refusal)  — input = Plan Items' item
//   Any Actions? false (plans, but nothing to create/update)        — input = Decide's item
//   Apply (one response per create/update, same order as Split Actions)
// Issue numbers/URLs come only from GitHub's response and are re-validated; agent text only goes in the body.
const header = (s, n) => String(s || '').replace(/[^\x20-\x7E]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const get = (name, all) => { try { return all ? $(name).all().map(i => i.json) : $(name).first().json; } catch (e) { return all ? [] : null; } };
const pi = get('Plan Items') || {};
const be = get('Build Event') || {};
const decide = get('Decide');
const sent = get('Split Actions', true);
const repo = String(pi.plans_repo || '');
const ISSUE_URL = new RegExp(`^https://github\\.com/${repo.replace(/[.]/g, '\\.')}/issues/(\\d+)$`);

const input = $input.all().map(i => i.json || {});
const applied = new Map();   // fingerprint -> {status, number, url}
if (sent.length && input.length === sent.length && input.every(r => 'statusCode' in r || 'error' in r)) {
  input.forEach((r, i) => {
    const a = sent[i], code = Number(r.statusCode || 0), b = (r.body && typeof r.body === 'object') ? r.body : {};
    const okCode = a.method === 'POST' ? 201 : 200;
    const m = typeof b.html_url === 'string' ? b.html_url.match(ISSUE_URL) : null;
    applied.set(a.fingerprint, { ok: code === okCode, status: code || null,
      number: m && Number.isInteger(b.number) && String(b.number) === m[1] ? b.number : (a.issue_number || null),
      url: m ? b.html_url : null, error: r.error ? String(r.error.message || r.error).slice(0, 200) : null });
  });
}

const filings = [], counts = { created: [], updated: [], unchanged: [], skip_accepted: [], not_filed: [], failed: [] };
for (const d of (decide && decide.decisions) || []) {
  let action = d.action, number = d.issue_number || null, url = null, status = null, detail = d.reason || null;
  if (action === 'create' || action === 'update') {
    const r = applied.get(d.fingerprint);
    if (!r || !r.ok) { status = r ? r.status : null; detail = r ? (r.error || `HTTP ${r.status}`) : 'not applied'; action = `${action}_failed`; }
    else { status = r.status; number = r.number; url = r.url; }
  }
  if (number && !url) url = `https://github.com/${repo}/issues/${number}`;
  filings.push({ run_id: pi.run_id, fingerprint: d.fingerprint, rule: d.rule, resource: d.resource, severity: d.severity,
                 action, issue_number: number, issue_url: url, http_status: status, detail });
  const key = { create: 'created', update: 'updated', unchanged: 'unchanged', skip_accepted: 'skip_accepted',
                not_filed: 'not_filed' }[action] || 'failed';
  counts[key].push({ n: number, title: d.title, sev: d.severity, why: detail });
}

const refused = /^refused_|^runner_unreachable$/.test(String(pi.exit_reason || ''));
const label = be.label || 'sec-researcher run';
const nums = xs => xs.map(x => (x.n ? `#${x.n}` : '?')).join(', ');
const lines = [`${refused ? 'Not started' : 'Run'}: ${label}`, String(pi.summary || '(no summary)').slice(0, 1000)];
const planned = (pi.plans || []).length;
if (planned || (decide && decide.decisions && decide.decisions.length)) {
  lines.push(`Plans: ${counts.created.length} created${counts.created.length ? ` (${nums(counts.created)})` : ''}, `
    + `${counts.updated.length} updated${counts.updated.length ? ` (${nums(counts.updated)})` : ''}, `
    + `${counts.unchanged.length} unchanged, ${counts.skip_accepted.length} skipped (accepted risk), `
    + `${counts.not_filed.length} not filed${counts.failed.length ? `, ${counts.failed.length} FAILED` : ''}.`);
  for (const x of counts.not_filed.slice(0, 5)) lines.push(`- not filed [${x.sev}] ${String(x.title).slice(0, 120)} (${x.why})`);
  if (counts.not_filed.length > 5) lines.push(`- …and ${counts.not_filed.length - 5} more not filed (agent_plan_filings)`);
  for (const x of counts.failed.slice(0, 3)) lines.push(`- FAILED [${x.sev}] ${String(x.title).slice(0, 120)} (${x.why})`);
}
if (pi.invalid || pi.duplicate) lines.push(`Dropped by n8n: ${pi.invalid || 0} malformed, ${pi.duplicate || 0} duplicate plan(s).`);
if (repo && (counts.created.length || counts.updated.length)) lines.push(`https://github.com/${repo}/issues?q=label%3Asec-researcher`);
lines.push(`run ${pi.run_id || '?'} · ${pi.exit_reason || '?'}`);

const sevNew = counts.created.map(x => x.sev);
const priority = counts.failed.length || pi.outcome === 'failed' ? (refused ? '3' : '4')
  : sevNew.some(s => s === 'critical' || s === 'high') ? '4' : counts.created.length ? '3' : '2';
const tags = counts.failed.length || pi.outcome === 'failed' ? 'warning,lock' : counts.created.length ? 'memo,lock' : 'lock';
const title = refused
  ? `sec-researcher: not started - ${label}`
  : `sec-researcher: ${pi.outcome || 'failed'} - ${counts.created.length} new, ${counts.updated.length} updated - ${label}`;

return [{ json: { title: header(title, 120), message: lines.join('\n'), tags, priority, filings } }];
